(window.LADDER_CARDS=window.LADDER_CARDS||{})["45a"]=[{"q": "How many values does a 32-bit address take?", "a": "2³², about 4.29 billion", "w": ["32", "2¹²⁸", "4 million"], "why": "Each bit doubles the count."}, {"q": "What is the grouping of an address into dotted or coloned parts for?", "a": "the eye; the machine sees one number", "w": ["the router's speed", "splitting the network", "error checking"], "why": "45a1: the written form is for people."}, {"q": "In 2001:db8::1, how many zero groups does :: stand for?", "a": "five", "w": ["one", "two", "as many as you like"], "why": "Eight groups less the three shown."}, {"q": "Why may :: appear only once in an address?", "a": "two would split the missing zeros in more than one way", "w": ["it saves ink", "routers forbid it", "hex has no second colon"], "why": "One reading per spelling is proved from the fixed width."}, {"q": "How many addresses does 192.0.2.0/24 cover?", "a": "256", "w": ["24", "24 million", "one"], "why": "32 − 24 = 8 free bits, 2⁸ = 256."}, {"q": "Two prefixes share one address. How do they lie?", "a": "one lies wholly inside the other", "w": ["they overlap partly", "they are equal", "they are disjoint"], "why": "The shorter is a beginning of the longer."}, {"q": "Several prefixes match a destination. Which line does a router use?", "a": "the longest", "w": ["the shortest", "the first found", "the default"], "why": "Longest-prefix technique."}, {"q": "What does best effort promise?", "a": "a try at each hop, and nothing more", "w": ["delivery", "delivery in order", "delivery once"], "why": "45a4: lost, late, doubled or reordered packets are all allowed."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["45b"]=[{"q": "A machine’s next move is a function of what?", "a": "its own state and the messages it has received", "w": ["the shared clock", "every machine’s state", "the time"], "why": "Its view, and nothing else."}, {"q": "Two runs give a machine the same view. What does it do?", "a": "the same move in both", "w": ["different moves", "nothing", "it waits"], "why": "Same-view technique."}, {"q": "No bound on delay. Can a machine tell a crashed machine from a slow one?", "a": "no", "w": ["yes, by waiting", "yes, by the clock", "only after a while"], "why": "Every message the slow one sent may still be on its way."}, {"q": "“B has not answered for a long time, so B crashed.” Is it safe?", "a": "no: a slow B looks the same", "w": ["yes", "yes, after d seconds", "only if B is far"], "why": "Waiting longer only moves the moment."}, {"q": "Every message arrives within a known time d. What does silence longer than d mean?", "a": "a crash", "w": ["a slow machine", "nothing", "a lie"], "why": "Bounds change the model."}, {"q": "Messages arrive in the order sent?", "a": "not in this model", "w": ["always", "when there is no loss", "only on one link"], "why": "Any order is allowed."}, {"q": "The model with no bound on delay. Accepted name?", "a": "asynchronous", "w": ["synchronous", "partially synchronous", "clocked"], "why": "The cellar names the three models."}, {"q": "Bounds that usually hold and sometimes do not. Accepted name?", "a": "partial synchrony", "w": ["synchrony", "asynchrony", "a crash fault"], "why": "Real networks lie between the two."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["45c"]=[{"q": "Two generals, a messenger who may be caught. Is any plan safe?", "a": "no", "w": ["yes, with enough messages", "yes, with acknowledgments", "yes, if both are honest"], "why": "45c3 removes every message."}, {"q": "The sender of the last message cannot know it arrived. What follows?", "a": "the last message was not needed", "w": ["it must resend", "the plan is safe", "the receiver attacks alone"], "why": "Last-message technique."}, {"q": "After all removals: A says yes, nothing arrives, both attack. Then A says no, nothing arrives. What does B do?", "a": "attacks", "w": ["retreats", "waits", "asks again"], "why": "B’s view is the same in both runs."}, {"q": "Acknowledge the acknowledgments until sure. Does it work?", "a": "no: the last one can be lost", "w": ["yes", "yes, after three", "only on short links"], "why": "It was not needed."}, {"q": "k messengers, each caught with chance q. Chance all are caught?", "a": "qᵏ", "w": ["kq", "1 − qᵏ", "q/k"], "why": "41i: the catches are independent."}, {"q": "Do the generals fail because one lies?", "a": "no: messages are lost", "w": ["yes", "only the second", "only if both lie"], "why": "Liars are 45h."}, {"q": "What can a lossy link give, in place of certainty?", "a": "a chance as near 1 as you like", "w": ["certainty after enough tries", "nothing", "certainty with acknowledgments"], "why": "Agreement with chance 1 − qᵏ."}, {"q": "Accepted name of the puzzle?", "a": "the two generals problem", "w": ["the Byzantine generals", "the dining philosophers", "the halting problem"], "why": "Also called coordinated attack."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["45d"]=[{"q": "Number each message, resend until acknowledged, drop repeats. What does it give?", "a": "every message delivered in order, once", "w": ["certainty after the handshake", "no losses", "a shared clock"], "why": "With chance 1, by the resend technique."}, {"q": "Each try succeeds with chance p > 0. Chance k tries all fail is at most?", "a": "(1 − p)ᵏ", "w": ["pᵏ", "1 − pᵏ", "kp"], "why": "It falls below any positive number."}, {"q": "Opening a connection takes how many messages?", "a": "three", "w": ["two", "one", "four"], "why": "a; b with a + 1; b + 1."}, {"q": "Why are starting numbers picked fresh, not 0?", "a": "so an old stray message is not taken for new", "w": ["to save bits", "to make it faster", "so the clock wraps"], "why": "45d2."}, {"q": "Sequence numbers on the internet count on a clock of how many hours?", "a": "2³²", "w": ["2¹⁶", "2³¹", "10⁹"], "why": "32 bits."}, {"q": "On that clock, which is newer: 5 or 2³² − 3?", "a": "5", "w": ["2³² − 3", "neither", "both"], "why": "The count wrapped."}, {"q": "The closing side waits before forgetting. Why?", "a": "its last acknowledgment may be lost", "w": ["to save power", "the clock must wrap", "the handshake needs it"], "why": "45c still holds for the last message."}, {"q": "The three-message opening. Accepted name?", "a": "the three-way handshake", "w": ["two-phase commit", "the sliding window", "TIME-WAIT"], "why": "With SYN and ACK messages, in TCP."}];
