(window.LADDER_CARDS=window.LADDER_CARDS||{})["45h"]=[{"q": "Three generals, one traitor, forgeable messages. Can a plan meet the demands?", "a": "no", "w": ["yes", "yes, with a vote", "only if the commander is honest"], "why": "45h2."}, {"q": "Agreement despite f liars with forgeable messages needs how many machines?", "a": "more than 3f", "w": ["more than 2f", "more than f", "f + 1"], "why": "Third-bound technique."}, {"q": "n = 3f + 1, quorums of 2f + 1. Two quorums share at least?", "a": "f + 1", "w": ["f", "1", "2f"], "why": "2(2f + 1) − (3f + 1)."}, {"q": "Why must two quorums share f + 1?", "a": "at least one shared machine is honest", "w": ["for speed", "to outvote the leader", "to fill a grid"], "why": "The f liars could fill the rest."}, {"q": "Every message signed. How many traitors can agreement handle?", "a": "any number, given enough rounds", "w": ["fewer than a third", "none", "one"], "why": "A traitor cannot forge another’s signature."}, {"q": "A machine that may say anything. Its fault is called?", "a": "a Byzantine fault", "w": ["a crash fault", "an omission", "a timeout"], "why": "The cellar names it."}, {"q": "An honest majority is enough against liars?", "a": "no: more than two thirds", "w": ["yes", "yes, with clocks", "only for three"], "why": "Third-bound technique."}, {"q": "Methods with two-thirds quorums. Accepted name?", "a": "Byzantine fault tolerant", "w": ["crash tolerant", "eventually consistent", "proof of work"], "why": "PBFT the best known."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["45i"]=[{"q": "In an open network one person runs a thousand machines. What fails?", "a": "counting votes", "w": ["signatures", "the chain", "the scrambling function"], "why": "So votes become work."}, {"q": "The right to add a block is won how?", "a": "by finding a rare number by trying", "w": ["by majority vote", "by signature", "by the clock"], "why": "Chance in proportion to work done."}, {"q": "Which chain does every machine follow?", "a": "the one with the most work", "w": ["the longest by time", "the first seen", "the leader’s"], "why": "45i2."}, {"q": "Attacker share q, honest p > 1/2, z blocks behind. Chance to catch up?", "a": "(q/p)ᶻ", "w": ["qᶻ", "q/p", "1 − (q/p)ᶻ"], "why": "Catch-up technique."}, {"q": "Is a block final when added?", "a": "no: it grows safer with each block after", "w": ["yes", "after one block", "only if signed"], "why": "Final with chance 1 − (q/p)ᶻ."}, {"q": "More machines, more votes?", "a": "no: only work counts", "w": ["yes", "yes, if honest", "only in pools"], "why": "However the work is split."}, {"q": "Members known. What is used instead?", "a": "two-thirds quorums", "w": ["more work", "longer chains", "gossip"], "why": "Back to quorums."}, {"q": "Following the chain with most work. Accepted name?", "a": "Nakamoto consensus", "w": ["Paxos", "PBFT", "gossip"], "why": "Proof of work; the catch-up technique is the gambler’s ruin."}];
