(window.LADDER_CARDS=window.LADDER_CARDS||{})["45k"]=[{"q": "On the ring, which machine holds a key?", "a": "the first at or after it", "w": ["the nearest before it", "key mod n", "the leader"], "why": "45k1."}, {"q": "A machine joins. Which keys change hands?", "a": "only those just before it", "w": ["every key", "half the keys", "none"], "why": "Ring-move technique."}, {"q": "Keys held at “key mod n”. What happens when n changes?", "a": "almost every key moves", "w": ["none move", "only 1/n move", "only one moves"], "why": "Why the ring is used."}, {"q": "Fingers about 1/2, 1/4, 1/8 of the way round. Hops per lookup?", "a": "about log₂ n", "w": ["n", "n/2", "1"], "why": "Each hop at least halves the distance."}, {"q": "Distance by exactly-one, place by place. Does it keep the triangle law?", "a": "yes: exactly-one never carries", "w": ["no", "only for small names", "only on a ring"], "why": "x ⊕ y ≤ x + y."}, {"q": "Why not one list of every key?", "a": "one machine to fail and to ask", "w": ["it is too small", "it wraps", "it needs a clock"], "why": "The ring shares the work."}, {"q": "A network that spreads keys this way. Accepted name?", "a": "a distributed hash table", "w": ["a blockchain", "a CRDT", "a quorum system"], "why": "Built on consistent hashing."}, {"q": "The exactly-one distance. Accepted name?", "a": "the XOR metric", "w": ["the Hamming bound", "the finger table", "the ring move"], "why": "Kademlia’s, used by BitTorrent."}];
